import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { Quaternion, Texture } from 'three';
import type { AnimationClip } from 'three';
import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';
import { expect } from 'vitest';

export const wardenModel = 'imported/responder-trellis/model/responder.glb';
export const wardenJoints = ['knee-left', 'knee-right', 'helmet'] as const;
// Independent observations from Sol's unmodified winning route, not generated by the mixer test.
export const approachHashes = { 5348: '11709b0d651208ee', 5349: '9325607625a6fb13' } as const;

/** Keep the shipped skin and keyframes; image decoding is the only browser-only boundary. */
export function loadWarden() {
  const bytes = Uint8Array.from(readFileSync(`games/horror/assets/${wardenModel}`));
  return new GLTFLoader()
    .register(() => ({ name: 'headless-images', loadTexture: async () => new Texture() }))
    .parseAsync(bytes.buffer, '');
}

export function clipRotation(
  clips: readonly AnimationClip[],
  name: string,
  joint: string,
  seconds: number,
) {
  const track = clips
    .find((clip) => clip.name === name)
    ?.tracks.find((t) => t.name === `${joint}.quaternion`);
  assert.ok(track, `${name}: missing ${joint} rotation track`);
  return new Quaternion().fromArray(track.createInterpolant().evaluate(seconds)).normalize();
}

/** Independent clip samples for the direct-target finish on the unmodified, unquantized win route. */
export function expectApproachPose(
  clips: readonly AnimationClip[],
  tick: number,
  rotations: number[][],
) {
  const searchAge = Math.max(0, tick - 5349);
  for (const [i, joint] of wardenJoints.entries()) {
    const gait = clipRotation(clips, 'Stalk', joint, ((tick - 5319) * 2.0625) / 60);
    const search = clipRotation(clips, 'Search', joint, searchAge / 60);
    const expected = gait.slerp(search, Math.min(1, searchAge / 8));
    const actual = new Quaternion().fromArray(rotations[i]!).normalize();
    expect(actual.angleTo(expected), `${joint} at tick ${tick} (radians)`).toBeLessThan(1e-5);
  }
}
